import java.io.BufferedReader; import java.io.InputStreamReader; import java.io.IOException; import java.util.HashSet; import java.util.Set; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int y = Integer.parseInt(br.readLine()); int nextYear = y + 1; while (true) { if (hasDistinctDigits(nextYear)) { System.out.println(nextYear); break; } nextYear++; } } private static boolean hasDistinctDigits(int year) { String s = String.valueOf(year); Set<Character> seen = new HashSet<>(); for (char c : s.toCharArray()) { if (!seen.add(c)) { return false; } } return true; } }